#!/bin/sh
# ABOUTME: SessionStart(compact|clear) reminder hook; SPACEDOCK_BIN gates it to launcher-marked sessions only — do not strip as dead weight.
[ -n "${SPACEDOCK_BIN:-}" ] || exit 0
printf '%s\n' '{"hookSpecificOutput":{"hookEventName":"SessionStart","additionalContext":"CONTEXT BOUNDARY (compaction or clear) — your bindings are stale, not just your narrative. A summary claiming you read or did something is not the reading or the doing.\n\nYou are mid-loop: do NOT greet, re-present a session summary, or wait to be engaged again. Before the next workflow effect, re-satisfy each load precondition and state read at its existing trigger — re-read a deferred contract at the point that needs it, and take a fresh `${SPACEDOCK_BIN:-spacedock} status --boot --identify --json`, reading the whole record and not only the keys you came for. Then resume the loop where it stopped.\n\nDistrust specifically: which gates you believe are presented (check readiness, not memory), which workers you believe are alive, the SPACEDOCK_BIN path, and which contract version is installed."}}'
